 {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n\n\n\n.section-header[_ngcontent-%COMP%]   h2[_ngcontent-%COMP%]::after {\n  content: \"\";\n  width: 80px;\n  height: 4px;\n  background: linear-gradient(90deg, var(--primary-color), var(--secondary-color));\n  position: absolute;\n  bottom: -10px;\n  left: 50%;\n  transform: translateX(-50%);\n  border-radius: 2px;\n}\n\n\n\n\n\n.bg-quindio-gradient[_ngcontent-%COMP%] {\n  background: linear-gradient(135deg, var(--primary-color) 0%, var(--secondary-color) 100%);\n  position: relative;\n  overflow: hidden;\n}\n.bg-quindio-gradient[_ngcontent-%COMP%]::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background: url('data:image/svg+xml,<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\"><polygon points=\"0,0 100,0 80,100 0,100\" fill=\"white\" opacity=\"0.05\"/></svg>');\n  background-size: 200px 100px;\n}\n\n.cta-content[_ngcontent-%COMP%] {\n  text-align: center;\n  position: relative;\n  z-index: 2;\n}\n\n.cta-title[_ngcontent-%COMP%] {\n  color: var(--background-white);\n  font-size: var(--font-size-3xl);\n  font-weight: var(--font-weight-bold);\n  margin-bottom: var(--spacing-lg);\n  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);\n}\n\n.cta-subtitle[_ngcontent-%COMP%] {\n  color: rgba(255, 255, 255, 0.9);\n  font-size: var(--font-size-lg);\n  margin-bottom: var(--spacing-2xl);\n  max-width: 600px;\n  margin-left: auto;\n  margin-right: auto;\n  line-height: 1.6;\n}\n\n.cta-buttons[_ngcontent-%COMP%] {\n  display: flex;\n  justify-content: center;\n  gap: var(--spacing-lg);\n  flex-wrap: wrap;\n}\n\n.cta-btn-primary[_ngcontent-%COMP%] {\n  background: var(--background-white);\n  color: var(--primary-color);\n}\n.cta-btn-primary[_ngcontent-%COMP%]:hover:not(:disabled) {\n  background: rgba(255, 255, 255, 0.9);\n  transform: translateY(-2px);\n  box-shadow: var(--shadow-lg);\n}\n\n.cta-btn-secondary[_ng